  "headline": "FDA's records show our tramadol hydrochloride supply is labeled by A-S Medication Solutions, which received a Warning Letter on 2017-06-05 and was last inspected with a VAI classification on 2026-08-12",
  "headline_cites": ["E9", "E8", "E7"],
  "sentences": [
    {
      "text": "The product label for tramadol hydrochloride (NDC 50090578902) identifies A-S Medication Solutions as the labeler and registered plant (FEI 1450743).",
      "cites": ["E9"]
    },
    {
      "text": "FDA issued a Warning Letter to A-S Medication Solutions LLC on 2017-06-05 (case 522197).",
      "cites": ["E8"]
    },
    {
      "text": "The most recent FDA inspection of this facility ended on 2026-08-12 and was classified VAI, with the classification known to FDA on 2026-10-14.",
      "cites": ["E7"]
    },
    {
      "text": "Prior inspections in 2009, 2012, 2013, and 2018 were also classified VAI.",
      "cites": ["E3", "E4", "E5", "E6"]
    },
    {
      "text": "Corvale East has 303 units on hand at 18.1 units per day, providing 17 days of supply.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General has 532 units on hand at 18.4 units per day, providing 29 days of supply.",
      "cites": ["D2"]
    }
  ]
}
